49	const (
50		preloadSize    = 100
51		checkDoneEvery = 128
52	)
53	
54	var nilResult = model.MeasureQueryResult(nil)
55	
56	var queryResultTracker = pool.RegisterTracker("measure.queryResult")
57	
58	// Query allow to retrieve measure data points.
59	type Query interface {
60		LoadGroup(name string) (resourceSchema.Group, bool)
61		Measure(measure *commonv1.Metadata) (Measure, error)
62		GetRemovalSegmentsTimeRange(group string) *timestamp.TimeRange
63	}
64	
65	// Measure allows inspecting measure data points' details.
66	type Measure interface {
67		Query(ctx context.Context, opts model.MeasureQueryOptions) (model.MeasureQueryResult, error)
68		GetSchema() *databasev1.Measure
69		GetIndexRules() []*databasev1.IndexRule
70	}
71	
72	var _ Measure = (*measure)(nil)
73	
74	type queryOptions struct {
75		schemaTagTypes map[string]pbv1.ValueType
76		model.MeasureQueryOptions
77		vectorized   vmeasure.VectorizedConfig
78		minTimestamp int64
79		maxTimestamp int64
80	}
81	
82	type topNQueryOptions struct {
83		sortDirection modelv1.Sort
84		number        int32
85		fieldType     databasev1.FieldType
86	}
87	
88	func (m *measure) Query(ctx context.Context, mqo model.MeasureQueryOptions) (mqr model.MeasureQueryResult, err error) {
89		startTime := time.Now()
90		ctx = panicdiag.WithBreadcrumb(ctx, "start measure query", "measure", map[string]string{
91			"group":   m.group,
92			"measure": mqo.Name,
93		})
94		defer func() {
95			if m.queryMetrics != nil {
96				m.queryMetrics.queryLatency.Observe(time.Since(startTime).Seconds())
97				if err != nil {
98					m.queryMetrics.queryErrors.Inc(1)
99				}
100			}
101		}()
102	
103		if validateErr := validateMeasureQueryOptions(mqo); validateErr != nil {
104			return nil, validateErr
105		}
106	
107		var tsdb storage.TSDB[*tsTable, option]
108		db := m.tsdb.Load()
109		if db == nil {
110			tsdb, err = m.schemaRepo.loadTSDB(m.group)
111			if err != nil {
112				return nil, err
113			}
114			m.tsdb.Store(tsdb)
115		} else {
116			tsdb = db.(storage.TSDB[*tsTable, option])
117		}
118	
119		segments, err := tsdb.SelectSegments(*mqo.TimeRange, true)
120		if err != nil {
121			return nil, err
122		}
123		if len(segments) < 1 {
124			return nilResult, nil
125		}
126		ctx = panicdiag.WithBreadcrumb(ctx, "selected measure segments", "measure", map[string]string{
127			"group":    m.group,
128			"segments": fmt.Sprintf("%d", len(segments)),
129		})
130		segmentsNeedRelease := true
131		defer func() {
132			if !segmentsNeedRelease {
133				return
134			}
135			for i := range segments {
136				segments[i].DecRef()
137			}
138		}()
139	
140		if m.schema.IndexMode {
141			segmentsNeedRelease = false
142			ctx = panicdiag.WithBreadcrumb(ctx, "build indexed measure query result", "measure", map[string]string{
143				"group":   m.group,
144				"measure": mqo.Name,
145			})
146			return m.buildIndexQueryResult(ctx, mqo, segments)
147		}
148	
149		if validateErr := validateMeasureEntities(mqo); validateErr != nil {
150			return nil, validateErr
151		}
152	
153		series := make([]*pbv1.Series, len(mqo.Entities))
154		for i := range mqo.Entities {
155			series[i] = &pbv1.Series{
156				Subject:      mqo.Name,
157				EntityValues: mqo.Entities[i],
158			}
159		}
160	
161		sids, tables, tableShardIDs, caches, storedIndexValue, newTagProjection, err := m.searchSeriesList(ctx, series, mqo, segments)
162		if err != nil {
163			return nil, err
164		}
165		if len(sids) < 1 {
166			return nilResult, nil
167		}
168		ctx = panicdiag.WithBreadcrumb(ctx, "resolved measure series", "measure", map[string]string{
169			"group":  m.group,
170			"series": fmt.Sprintf("%d", len(sids)),
171		})
172		result := queryResult{
173			ctx:              ctx,
174			qm:               m.queryMetrics,
175			segments:         segments,
176			tagProjection:    mqo.TagProjection,
177			storedIndexValue: storedIndexValue,
178		}
179		queryResultTracker.Acquire(&result)
180		if m.queryMetrics != nil {
181			m.queryMetrics.totalQueryResultStarted.Inc(1)
182		}
183		segmentsNeedRelease = false
184		defer func() {
185			if err != nil {
186				result.Release()
187			}
188		}()
189		mqo.TagProjection = newTagProjection
190	
191		schemaTagTypes := make(map[string]pbv1.ValueType)
192		for _, tf := range m.schema.GetTagFamilies() {
193			for _, tag := range tf.GetTags() {
194				vt := pbv1.TagValueSpecToValueType(tag.GetType())
195				if vt != pbv1.ValueTypeUnknown {
196					schemaTagTypes[tag.GetName()] = vt
197				}
198			}
199		}
200	
201		var parts []*part
202		qo := queryOptions{
203			MeasureQueryOptions: mqo,
204			schemaTagTypes:      schemaTagTypes,
205			minTimestamp:        mqo.TimeRange.Start.UnixNano(),
206			maxTimestamp:        mqo.TimeRange.End.UnixNano(),
207			vectorized:          m.vectorized,
208		}
209		var n int
210		for i := range tables {
211			s := tables[i].currentSnapshot()
212			if s == nil {
213				continue
214			}
215			oldLen := len(parts)
216			parts, n = s.getParts(parts, caches[i], qo.minTimestamp, qo.maxTimestamp)
217			if n < 1 {
218				s.decRef()
219				continue
220			}
221			// Set shard ID for newly added parts
222			for j := oldLen; j < len(parts); j++ {
223				parts[j].shardID = tableShardIDs[i]
224			}
225			result.snapshots = append(result.snapshots, s)
226		}
227	
228		ctx = panicdiag.WithBreadcrumb(ctx, "search measure blocks", "measure", map[string]string{
229			"group": m.group,
230			"parts": fmt.Sprintf("%d", len(parts)),
231		})
232		if err = m.searchBlocks(ctx, &result, sids, parts, qo); err != nil {
233			return nil, err
234		}
235	
236		applyMeasureQueryOrdering(mqo, &result)
237		applyTopNOptions(mqo, &result)
238	
239		if m.queryMetrics != nil {
240			m.queryMetrics.resultPoints.Observe(float64(len(result.data)))
241		}
242	
243		// Build the columnar BatchSchema once for PullBatch consumers (G5b).
244		// IMPORTANT: use result.tagProjection (the *original* projection
245		// captured before the entity/index tag strip) rather than mqo —
246		// mqo.TagProjection was rewritten to newTagProjection above and no
247		// longer carries entity-tag slots that the row path's copyAllTo
248		// fills via storedIndexValue. The batch path's column layout must
249		// match the vec adapter's expectation, which is the original
250		// projection. Falls back to nil on schema-build failure; PullBatch
251		// checks for nil and returns a clean error rather than degrading
252		// the row-path Pull().
253		// Thread GroupBy + Agg through so BuildBatchSchema emits native
254		// column types for the agg-relevant columns. Plain queries get
255		// passthrough; GroupBy+Agg queries get native int64/float64/string
256		// columns the BatchAggregation operator reads directly (computeKey +
257		// fold). Storage decoders (banyand/measure/batch_decode.go) handle
258		// both column shapes.
259		result.batchSchema, _ = vmeasure.BuildBatchSchema(m.schema, model.MeasureQueryOptions{
260			TagProjection:   result.tagProjection,
261			FieldProjection: mqo.FieldProjection,
262			GroupBy:         mqo.GroupBy,
263			Agg:             mqo.Agg,
264		})
265	
266		return &result, nil
267	}
268	
269	func validateMeasureQueryOptions(mqo model.MeasureQueryOptions) error {
270		if mqo.TimeRange == nil {
271			return errors.New("invalid query options: timeRange are required")
272		}
273		if len(mqo.TagProjection) == 0 && len(mqo.FieldProjection) == 0 {
274			return errors.New("invalid query options: tagProjection or fieldProjection is required")
275		}
276		return nil
277	}
278	
279	func validateMeasureEntities(mqo model.MeasureQueryOptions) error {
280		if len(mqo.Entities) < 1 {
281			return errors.New("invalid query options: series is required")
282		}
283		return nil
284	}
285	
286	func applyMeasureQueryOrdering(mqo model.MeasureQueryOptions, result *queryResult) {
287		if mqo.Order == nil {
288			result.ascTS = true
289			result.orderByTS = true
290			return
291		}
292		if mqo.Order.Sort == modelv1.Sort_SORT_ASC || mqo.Order.Sort == modelv1.Sort_SORT_UNSPECIFIED {
293			result.ascTS = true
294		}
295		result.orderByTS = mqo.Order.Type == index.OrderByTypeTime
296	}
297	
298	func applyTopNOptions(mqo model.MeasureQueryOptions, result *queryResult) {
299		if mqo.Name != TopNSchemaName {
300			return
301		}
302		result.topNQueryOptions = &topNQueryOptions{
303			sortDirection: mqo.Sort,
304			number:        mqo.Number,
305			fieldType:     mqo.TopNFieldType,
306		}
307	}
308	
309	type tagNameWithType struct {
310		fieldName string
311		typ       pbv1.ValueType
312	}
313	
314	func (m *measure) searchSeriesList(ctx context.Context, series []*pbv1.Series, mqo model.MeasureQueryOptions,
315		segments []storage.Segment[*tsTable, option],
316	) (sl []common.SeriesID, tables []*tsTable, tableShardIDs []common.ShardID, caches []storage.Cache, storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
317		newTagProjection []model.TagProjection, err error,
318	) {
319		var indexProjection []index.FieldKey
320		fieldToValueType := make(map[string]tagNameWithType)
321		var projectedEntityOffsets map[string]int
322		newTagProjection = make([]model.TagProjection, 0)
323		is := m.indexSchema.Load().(indexSchema)
324		for _, tp := range mqo.TagProjection {
325			var tagProjection model.TagProjection
326		TAG:
327			for _, n := range tp.Names {
328				for i := range m.schema.GetEntity().GetTagNames() {
329					if n == m.schema.GetEntity().GetTagNames()[i] {
330						if projectedEntityOffsets == nil {
331							projectedEntityOffsets = make(map[string]int)
332						}
333						projectedEntityOffsets[n] = i
334						continue TAG
335					}
336				}
337				if is.fieldIndexLocation != nil {
338					if fields, ok := is.fieldIndexLocation[tp.Family]; ok {
339						if field, ok := fields[n]; ok {
340							indexProjection = append(indexProjection, field.Key)
341							fieldToValueType[field.Key.Marshal()] = tagNameWithType{
342								fieldName: n,
343								typ:       field.Type,
344							}
345							continue TAG
346						}
347					}
348				}
349				tagProjection.Family = tp.Family
350				tagProjection.Names = append(tagProjection.Names, n)
351			}
352			if tagProjection.Family != "" {
353				newTagProjection = append(newTagProjection, tagProjection)
354			}
355		}
356	
357		// Collect all search results first
358		var segResults []*segResult
359		var needsSorting bool
360		seriesFilter := roaring.NewPostingList()
361	
362		for i := range segments {
363			sd, sortedValues, err := segments[i].IndexDB().Search(ctx, series, storage.IndexSearchOpts{
364				Query:       mqo.Query,
365				Order:       mqo.Order,
366				PreloadSize: preloadSize,
367				Projection:  indexProjection,
368			})
369			if err != nil {
370				return nil, nil, nil, nil, nil, nil, err
371			}
372			if len(sd.SeriesList) > 0 {
373				tt, shardIDs, cc := segments[i].TablesWithShardIDs()
374				tables = append(tables, tt...)
375				tableShardIDs = append(tableShardIDs, shardIDs...)
376				caches = append(caches, cc...)
377	
378				// Create segResult for this segment
379				sr := &segResult{
380					SeriesData:   sd,
381					sortedValues: sortedValues,
382					i:            0,
383				}
384				segResults = append(segResults, sr)
385	
386				// Check if we need sorting
387				if mqo.Order != nil && sortedValues != nil {
388					needsSorting = true
389				}
390			}
391		}
392	
393		// Sort if needed, otherwise use original order
394		if needsSorting && len(segResults) > 0 {
395			// Use segResultHeap to sort
396			segHeap := &segResultHeap{
397				results:  segResults,
398				sortDesc: mqo.Order.Sort == modelv1.Sort_SORT_DESC,
399			}
400			heap.Init(segHeap)
401	
402			// Extract sorted series IDs
403			for segHeap.Len() > 0 {
404				top := heap.Pop(segHeap).(*segResult)
405				series := top.SeriesList[top.i]
406	
407				if seriesFilter.Contains(uint64(series.ID)) {
408					// Move to next in this segment
409					top.i++
410					if top.i < len(top.SeriesList) {
411						heap.Push(segHeap, top)
412					}
413					continue
414				}
415	
416				seriesFilter.Insert(uint64(series.ID))
417				sl = append(sl, series.ID)
418	
419				// Build storedIndexValue for this series
420				var fieldResult map[string][]byte
421				if top.Fields != nil && top.i < len(top.Fields) {
422					fieldResult = top.Fields[top.i]
423				}
424				storedIndexValue = m.buildStoredIndexValue(
425					series.ID,
426					series.EntityValues,
427					fieldResult,
428					projectedEntityOffsets,
429					fieldToValueType,
430					storedIndexValue,
431				)
432	
433				// Move to next in this segment
434				top.i++
435				if top.i < len(top.SeriesList) {
436					heap.Push(segHeap, top)
437				}
438			}
439		} else {
440			// Original logic when no sorting is needed
441			for _, sr := range segResults {
442				for j := range sr.SeriesList {
443					if seriesFilter.Contains(uint64(sr.SeriesList[j].ID)) {
444						continue
445					}
446					seriesFilter.Insert(uint64(sr.SeriesList[j].ID))
447					sl = append(sl, sr.SeriesList[j].ID)
448	
449					var fieldResult map[string][]byte
450					if sr.Fields != nil && j < len(sr.Fields) {
451						fieldResult = sr.Fields[j]
452					}
453					storedIndexValue = m.buildStoredIndexValue(
454						sr.SeriesList[j].ID,
455						sr.SeriesList[j].EntityValues,
456						fieldResult,
457						projectedEntityOffsets,
458						fieldToValueType,
459						storedIndexValue,
460					)
461				}
462			}
463		}
464	
465		return sl, tables, tableShardIDs, caches, storedIndexValue, newTagProjection, nil
466	}
467	
468	func (m *measure) buildStoredIndexValue(
469		seriesID common.SeriesID,
470		entityValues []*modelv1.TagValue,
471		fieldResult map[string][]byte,
472		projectedEntityOffsets map[string]int,
473		fieldToValueType map[string]tagNameWithType,
474		storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
475	) map[common.SeriesID]map[string]*modelv1.TagValue {
476		if projectedEntityOffsets == nil && fieldResult == nil {
477			return storedIndexValue
478		}
479	
480		if storedIndexValue == nil {
481			storedIndexValue = make(map[common.SeriesID]map[string]*modelv1.TagValue)
482		}
483		tagValues := make(map[string]*modelv1.TagValue)
484		storedIndexValue[seriesID] = tagValues
485	
486		for name, offset := range projectedEntityOffsets {
487			if offset < 0 || offset >= len(entityValues) {
488				logger.Warningf("offset %d for tag %s is out of range for series ID %v", offset, name, seriesID)
489				tagValues[name] = pbv1.NullTagValue
490				continue
491			}
492			tagValues[name] = entityValues[offset]
493		}
494	
495		for f, v := range fieldResult {
496			if tnt, ok := fieldToValueType[f]; ok {
497				tagValues[tnt.fieldName] = mustDecodeTagValue(tnt.typ, v)
498			} else {
499				logger.Panicf("unknown field %s not found in fieldToValueType", f)
500			}
501		}
502	
503		return storedIndexValue
504	}
505	
506	func (m *measure) buildIndexQueryResult(ctx context.Context, mqo model.MeasureQueryOptions,
507		segments []storage.Segment[*tsTable, option],
508	) (model.MeasureQueryResult, error) {
509		defer func() {
510			for i := range segments {
511				segments[i].DecRef()
512			}
513		}()
514		is := m.indexSchema.Load().(indexSchema)
515		r := &indexSortResult{}
516		var indexProjection []index.FieldKey
517		for _, tp := range mqo.TagProjection {
518			tagFamilyLocation := tagFamilyLocation{
519				name:                   tp.Family,
520				fieldToValueType:       make(map[string]tagNameWithType),
521				projectedEntityOffsets: make(map[string]int),
522			}
523		TAG:
524			for _, n := range tp.Names {
525				tagFamilyLocation.tagNames = append(tagFamilyLocation.tagNames, n)
526				for i := range m.schema.GetEntity().GetTagNames() {
527					if n == m.schema.GetEntity().GetTagNames()[i] {
528						tagFamilyLocation.projectedEntityOffsets[n] = i
529						continue TAG
530					}
531				}
532				if is.fieldIndexLocation != nil {
533					if fields, ok := is.fieldIndexLocation[tp.Family]; ok {
534						if field, ok := fields[n]; ok {
535							indexProjection = append(indexProjection, field.Key)
536							tagFamilyLocation.fieldToValueType[n] = tagNameWithType{
537								fieldName: field.Key.Marshal(),
538								typ:       field.Type,
539							}
540							continue TAG
541						}
542					}
543				}
544				return nil, fmt.Errorf("tag %s not found in schema", n)
545			}
546			r.tfl = append(r.tfl, tagFamilyLocation)
547		}
548		var err error
549		opts := storage.IndexSearchOpts{
550			Query:       mqo.Query,
551			Order:       mqo.Order,
552			PreloadSize: preloadSize,
553			Projection:  indexProjection,
554			TimeRange:   mqo.TimeRange,
555		}
556		seriesFilter := roaring.NewPostingList()
557		for i := range segments {
558			sr := &segResult{}
559			sr.SeriesData, sr.sortedValues, err = segments[i].IndexDB().SearchWithoutSeries(ctx, opts)
560			if err != nil {
561				return nil, err
562			}
563			for j := 0; j < len(sr.SeriesList); j++ {
564				if seriesFilter.Contains(uint64(sr.SeriesList[j].ID)) {
565					sr.remove(j)
566					j--
567					continue
568				}
569				seriesFilter.Insert(uint64(sr.SeriesList[j].ID))
570			}
571			if len(sr.SeriesList) < 1 {
572				continue
573			}
574			r.segResults.results = append(r.segResults.results, sr)
575		}
576		if len(r.segResults.results) < 1 {
577			return nilResult, nil
578		}
579	
580		// Set sort order based on mqo.Order.Sort
581		if mqo.Order != nil && mqo.Order.Sort == modelv1.Sort_SORT_DESC {
582			r.segResults.sortDesc = true
583		}
584	
585		// G5b — build the columnar BatchSchema once for PullBatch consumers.
586		// Errors here are non-fatal for the row-path Pull(); PullBatch will
587		// return a clean error if batchSchema is nil at call time.
588		r.batchSchema, _ = vmeasure.BuildBatchSchema(m.schema, mqo)
589	
590		heap.Init(&r.segResults)
591		return r, nil
592	}
593	
594	func (m *measure) searchBlocks(ctx context.Context, result *queryResult, sids []common.SeriesID, parts []*part, qo queryOptions) error {
595		defFn := startBlockScanSpan(ctx, len(sids), parts, result)
596		defer defFn()
597		tstIter := generateTstIter()
598		defer releaseTstIter(tstIter)
599		originalSids := make([]common.SeriesID, len(sids))
600		copy(originalSids, sids)
601		sort.Slice(sids, func(i, j int) bool { return sids[i] < sids[j] })
602		tstIter.init(parts, sids, qo.minTimestamp, qo.maxTimestamp)
603		if tstIter.Error() != nil {
604			return fmt.Errorf("cannot init tstIter: %w", tstIter.Error())
605		}
606		var hit int
607		var totalBlockBytes uint64
608		quota := m.pm.AvailableBytes()
609		for tstIter.nextBlock() {
610			if hit%checkDoneEvery == 0 {
611				select {
612				case <-ctx.Done():
613					return errors.WithMessagef(ctx.Err(), "interrupt: scanned %d blocks, remained %d/%d parts to scan", len(result.data), len(tstIter.piHeap), len(tstIter.piPool))
614				default:
615				}
616			}
617			hit++
618			bc := generateBlockCursor()
619			p := tstIter.piHeap[0]
620			bc.init(p.p, p.curBlock, qo)
621			bc.shardID = p.p.shardID
622			result.data = append(result.data, bc)
623			totalBlockBytes += bc.bm.uncompressedSizeBytes
624			if quota >= 0 && totalBlockBytes > uint64(quota) {
625				return fmt.Errorf("block scan quota exceeded: used %d bytes, quota is %d bytes", totalBlockBytes, quota)
626			}
627		}
628		if tstIter.Error() != nil {
629			return fmt.Errorf("cannot iterate tstIter: %w", tstIter.Error())
630		}
631		if err := m.pm.AcquireResource(ctx, totalBlockBytes); err != nil {
632			return err
633		}
634		result.sidToIndex = make(map[common.SeriesID]int)
635		for i, si := range originalSids {
636			result.sidToIndex[si] = i
637		}
638		return nil
639	}
