641	func mustDecodeTagValue(valueType pbv1.ValueType, value []byte) *modelv1.TagValue {
642		if value == nil {
643			return pbv1.NullTagValue
644		}
645		switch valueType {
646		case pbv1.ValueTypeInt64:
647			return int64TagValue(convert.BytesToInt64(value))
648		case pbv1.ValueTypeStr:
649			return strTagValue(string(value))
650		case pbv1.ValueTypeBinaryData:
651			return binaryDataTagValue(value)
652		case pbv1.ValueTypeInt64Arr:
653			var values []int64
654			for i := 0; i < len(value); i += 8 {
655				values = append(values, convert.BytesToInt64(value[i:i+8]))
656			}
657			return int64ArrTagValue(values)
658		case pbv1.ValueTypeStrArr:
659			var values []string
660			bb := bigValuePool.Generate()
661			defer bigValuePool.Release(bb)
662			var err error
663			for len(value) > 0 {
664				bb.Buf, value, err = unmarshalVarArray(bb.Buf[:0], value)
665				if err != nil {
666					logger.Panicf("unmarshalVarArray failed: %v", err)
667				}
668				values = append(values, string(bb.Buf))
669			}
670			return strArrTagValue(values)
671		default:
672			logger.Panicf("unsupported value type: %v", valueType)
673			return nil
674		}
675	}
