810	func (qr *queryResult) Pull() *model.MeasureResult {
811		select {
812		case <-qr.ctx.Done():
813			return &model.MeasureResult{
814				Error: errors.WithMessagef(qr.ctx.Err(), "interrupt: hit %d", qr.hit),
815			}
816		default:
817		}
818		if !qr.loaded {
819			if len(qr.data) == 0 {
820				return nil
821			}
822	
823			cursorChan := make(chan int, len(qr.data))
824			measureBlockLogger := logger.GetLogger("measure-query-block-loader")
825			for i := 0; i < len(qr.data); i++ {
826				idx := i
827				go func() {
828					defer func() {
829						if r := recover(); r != nil {
830							measureBlockLogger.Error().Interface("panic", r).Msg("panic in parallel block loader")
831							cursorChan <- idx
832						}
833					}()
834					select {
835					case <-qr.ctx.Done():
836						cursorChan <- idx
837						return
838					default:
839					}
840					tmpBlock := generateBlock()
841					defer releaseBlock(tmpBlock)
842					if !qr.data[idx].loadData(tmpBlock) {
843						cursorChan <- idx
844						return
845					}
846					if qr.orderByTimestampDesc() {
847						qr.data[idx].idx = len(qr.data[idx].timestamps) - 1
848					}
849					cursorChan <- -1
850				}()
851			}
852	
853			blankCursorList := []int{}
854			for completed := 0; completed < len(qr.data); completed++ {
855				result := <-cursorChan
856				if result != -1 {
857					blankCursorList = append(blankCursorList, result)
858				}
859			}
860			select {
861			case <-qr.ctx.Done():
862				return &model.MeasureResult{
863					Error: errors.WithMessagef(qr.ctx.Err(), "interrupt: blank/total=%d/%d", len(blankCursorList), len(qr.data)),
864				}
865			default:
866			}
867			sort.Slice(blankCursorList, func(i, j int) bool {
868				return blankCursorList[i] > blankCursorList[j]
869			})
870			for _, index := range blankCursorList {
871				qr.data = append(qr.data[:index], qr.data[index+1:]...)
872			}
873			qr.loaded = true
874			heap.Init(qr)
875		}
876		if len(qr.data) == 0 {
877			return nil
878		}
879		if len(qr.data) == 1 {
880			r := &model.MeasureResult{}
881			bc := qr.data[0]
882			bc.copyAllTo(r, qr.storedIndexValue, qr.tagProjection, qr.orderByTimestampDesc())
883			qr.data = qr.data[:0]
884			releaseBlockCursor(bc)
885			return r
886		}
887		return qr.merge(qr.storedIndexValue, qr.tagProjection)
888	}
889	
890	func (qr *queryResult) Release() {
891		queryResultTracker.Release(qr)
892		if qr.qm != nil {
893			qr.qm.totalQueryResultFinished.Inc(1)
894		}
895		for i, v := range qr.data {
896			releaseBlockCursor(v)
897			qr.data[i] = nil
898		}
899		qr.data = qr.data[:0]
900		for i := range qr.snapshots {
901			qr.snapshots[i].decRef()
902		}
903		qr.snapshots = qr.snapshots[:0]
904		for i := range qr.segments {
905			qr.segments[i].DecRef()
906		}
907	}
908	
909	func (qr queryResult) Len() int {
910		return len(qr.data)
911	}
912	
913	func (qr queryResult) Less(i, j int) bool {
914		leftTS := qr.data[i].timestamps[qr.data[i].idx]
915		rightTS := qr.data[j].timestamps[qr.data[j].idx]
916		leftVersion := qr.data[i].versions[qr.data[i].idx]
917		rightVersion := qr.data[j].versions[qr.data[j].idx]
918		if qr.orderByTS {
919			if leftTS == rightTS {
920				if qr.data[i].bm.seriesID == qr.data[j].bm.seriesID {
921					// sort version in descending order if timestamps and seriesID are equal
922					return leftVersion > rightVersion
923				}
924				// sort seriesID in ascending order if timestamps are equal
925				return qr.data[i].bm.seriesID < qr.data[j].bm.seriesID
926			}
927			if qr.ascTS {
928				return leftTS < rightTS
929			}
930			return leftTS > rightTS
931		}
932		leftSIDIndex := qr.sidToIndex[qr.data[i].bm.seriesID]
933		rightSIDIndex := qr.sidToIndex[qr.data[j].bm.seriesID]
934		if leftSIDIndex == rightSIDIndex {
935			if leftTS == rightTS {
936				// sort version in descending order if timestamps and seriesID are equal
937				return leftVersion > rightVersion
938			}
939			// sort timestamps in ascending order if seriesID are equal
940			return leftTS < rightTS
941		}
942		return leftSIDIndex < rightSIDIndex
943	}
