966	func (qr *queryResult) merge(storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
967		tagProjection []model.TagProjection,
968	) *model.MeasureResult {
969		step := 1
970		if qr.orderByTimestampDesc() {
971			step = -1
972		}
973		result := &model.MeasureResult{}
974		var lastVersion int64
975		var lastSid common.SeriesID
976	
977		var isTopN bool
978		var topNLimit int32
979		var topNSort modelv1.Sort
980		var topNFieldType databasev1.FieldType
981	
982		if qr.topNQueryOptions != nil {
983			isTopN = true
984			topNLimit = qr.topNQueryOptions.number
985			topNSort = qr.topNQueryOptions.sortDirection
986			topNFieldType = qr.topNQueryOptions.fieldType
987		}
988	
989		for qr.Len() > 0 {
990			topBC := qr.data[0]
991			if lastSid != 0 && topBC.bm.seriesID != lastSid {
992				return result
993			}
994			lastSid = topBC.bm.seriesID
995	
996			if len(result.Timestamps) > 0 &&
997				topBC.timestamps[topBC.idx] == result.Timestamps[len(result.Timestamps)-1] {
998				if isTopN {
999					topBC.mergeTopNResult(result, storedIndexValue, topNLimit, topNSort, topNFieldType)
1000				} else if topBC.versions[topBC.idx] > lastVersion {
1001					topBC.replace(result, storedIndexValue)
1002				}
1003			} else {
1004				topBC.copyTo(result, storedIndexValue, tagProjection)
1005				lastVersion = topBC.versions[topBC.idx]
1006			}
1007	
1008			topBC.idx += step
1009	
1010			if qr.orderByTimestampDesc() {
1011				if topBC.idx < 0 {
1012					heap.Pop(qr)
1013				} else {
1014					heap.Fix(qr, 0)
1015				}
1016			} else {
1017				if topBC.idx >= len(topBC.timestamps) {
1018					heap.Pop(qr)
1019				} else {
1020					heap.Fix(qr, 0)
1021				}
1022			}
1023		}
1024	
1025		return result
1026	}
