1034	// Pull implements model.MeasureQueryResult.
1035	func (iqr *indexSortResult) Pull() *model.MeasureResult {
1036		if len(iqr.segResults.results) < 1 {
1037			return nil
1038		}
1039		if len(iqr.segResults.results) == 1 {
1040			if iqr.segResults.results[0].i >= len(iqr.segResults.results[0].SeriesList) {
1041				return nil
1042			}
1043			sr := iqr.segResults.results[0]
1044			r := iqr.copyTo(sr)
1045			sr.i++
1046			if sr.i >= len(sr.SeriesList) {
1047				iqr.segResults.results = iqr.segResults.results[:0]
1048			}
1049			return r
1050		}
1051		top := heap.Pop(&iqr.segResults)
1052		sr := top.(*segResult)
1053		r := iqr.copyTo(sr)
1054		sr.i++
1055		if sr.i < len(sr.SeriesList) {
1056			heap.Push(&iqr.segResults, sr)
1057		}
1058		return r
1059	}
