1063	func (iqr *indexSortResult) copyTo(src *segResult) (dest *model.MeasureResult) {
1064		index := src.i
1065		dest = &model.MeasureResult{
1066			SID:        src.SeriesList[index].ID,
1067			Timestamps: []int64{src.Timestamps[index]},
1068			Versions:   []int64{src.Versions[index]},
1069		}
1070		for i := range iqr.tfl {
1071			tagFamily := model.TagFamily{Name: iqr.tfl[i].name}
1072			peo := iqr.tfl[i].projectedEntityOffsets
1073			var fr storage.FieldResult
1074			if src.Fields != nil {
1075				fr = src.Fields[index]
1076			}
1077			for _, n := range iqr.tfl[i].tagNames {
1078				if offset, ok := peo[n]; ok {
1079					tagFamily.Tags = append(tagFamily.Tags, model.Tag{
1080						Name:   n,
1081						Values: []*modelv1.TagValue{src.SeriesList[index].EntityValues[offset]},
1082					})
1083					continue
1084				}
1085				if fr == nil {
1086					continue
1087				}
1088				if tnt, ok := iqr.tfl[i].fieldToValueType[n]; ok {
1089					tagFamily.Tags = append(tagFamily.Tags, model.Tag{
1090						Name:   n,
1091						Values: []*modelv1.TagValue{mustDecodeTagValue(tnt.typ, fr[tnt.fieldName])},
1092					})
1093				} else {
1094					logger.Panicf("unknown field %s not found in fieldToValueType", n)
1095				}
1096			}
1097			dest.TagFamilies = append(dest.TagFamilies, tagFamily)
1098		}
1099		return dest
1100	}
