1127	type segResultHeap struct {
1128		results  []*segResult
1129		sortDesc bool
1130	}
1131	
1132	func (h *segResultHeap) Len() int { return len(h.results) }
1133	func (h *segResultHeap) Less(i, j int) bool {
1134		// Handle NPE - check for nil results or invalid indices
1135		if i >= len(h.results) || j >= len(h.results) {
1136			return false
1137		}
1138		if h.results[i] == nil || h.results[j] == nil {
1139			return false
1140		}
1141		if h.results[i].i >= len(h.results[i].SeriesList) || h.results[j].i >= len(h.results[j].SeriesList) {
1142			return false
1143		}
1144	
1145		// If no sortedValues, compare by SeriesID
1146		if h.results[i].sortedValues == nil || h.results[j].sortedValues == nil {
1147			if h.sortDesc {
1148				return h.results[i].SeriesList[h.results[i].i].ID > h.results[j].SeriesList[h.results[j].i].ID
1149			}
1150			return h.results[i].SeriesList[h.results[i].i].ID < h.results[j].SeriesList[h.results[j].i].ID
1151		}
1152	
1153		// Handle potential index out of bounds for sortedValues
1154		if h.results[i].i >= len(h.results[i].sortedValues) || h.results[j].i >= len(h.results[j].sortedValues) {
1155			if h.sortDesc {
1156				return h.results[i].SeriesList[h.results[i].i].ID > h.results[j].SeriesList[h.results[j].i].ID
1157			}
1158			return h.results[i].SeriesList[h.results[i].i].ID < h.results[j].SeriesList[h.results[j].i].ID
1159		}
1160	
1161		cmp := bytes.Compare(h.results[i].sortedValues[h.results[i].i], h.results[j].sortedValues[h.results[j].i])
1162		if h.sortDesc {
1163			return cmp > 0
1164		}
1165		return cmp < 0
1166	}
1167	func (h *segResultHeap) Swap(i, j int) { h.results[i], h.results[j] = h.results[j], h.results[i] }
1168	
1169	func (h *segResultHeap) Push(x interface{}) {
1170		h.results = append(h.results, x.(*segResult))
1171	}
1172	
1173	func (h *segResultHeap) Pop() interface{} {
1174		old := h.results
1175		n := len(old)
1176		x := old[n-1]
1177		h.results = old[0 : n-1]
1178		return x
1179	}
