48	func (b *block) reset() {
49		b.timestamps = b.timestamps[:0]
50		b.versions = b.versions[:0]
51	
52		tff := b.tagFamilies
53		for i := range tff {
54			tff[i].reset()
55		}
56		b.tagFamilies = tff[:0]
57		b.field.reset()
58	}
59	
60	func (b *block) mustInitFromDataPoints(timestamps []int64, versions []int64, tagFamilies [][]nameValues, fields []nameValues) {
61		b.reset()
62		size := len(timestamps)
63		if size == 0 {
64			return
65		}
66		if size != len(tagFamilies) {
67			logger.Panicf("the number of timestamps %d must match the number of tagFamilies %d", size, len(tagFamilies))
68		}
69		if size != len(fields) {
70			logger.Panicf("the number of timestamps %d must match the number of fields %d", size, len(fields))
71		}
72	
73		assertTimestampsSorted(timestamps)
74		b.timestamps = append(b.timestamps, timestamps...)
75		b.versions = append(b.versions, versions...)
76		b.mustInitFromTagsAndFields(tagFamilies, fields)
77	}
78	
79	func assertTimestampsSorted(timestamps []int64) {
80		for i := range timestamps {
81			if i > 0 && timestamps[i-1] > timestamps[i] {
82				logger.Panicf("data points must be sorted by timestamp; got the previous data point with bigger timestamp %d than the current data point with timestamp %d",
83					timestamps[i-1], timestamps[i])
84			}
85		}
86	}
87	
88	func (b *block) mustInitFromTagsAndFields(tagFamilies [][]nameValues, fields []nameValues) {
89		dataPointsLen := len(tagFamilies)
90		if dataPointsLen == 0 {
91			return
92		}
93		for i, tff := range tagFamilies {
94			b.processTagFamilies(tff, i, dataPointsLen)
95		}
96		for i, f := range fields {
97			columns := b.field.resizeColumns(len(f.values))
98			for j, t := range f.values {
99				columns[j].name = t.name
100				columns[j].resizeValues(dataPointsLen)
101				columns[j].valueType = t.valueType
102				columns[j].values[i] = t.marshal()
103			}
104		}
105	}
106	
107	func (b *block) processTagFamilies(tff []nameValues, i int, dataPointsLen int) {
108		tagFamilies := b.resizeTagFamilies(len(tff))
109		for j, tf := range tff {
110			tagFamilies[j].name = tf.name
111			b.processTags(tf, j, i, dataPointsLen)
112		}
113	}
114	
115	func (b *block) processTags(tf nameValues, columnFamilyIdx, i int, dataPointsLen int) {
116		columns := b.tagFamilies[columnFamilyIdx].resizeColumns(len(tf.values))
117		for j, t := range tf.values {
118			columns[j].name = t.name
119			columns[j].resizeValues(dataPointsLen)
120			columns[j].valueType = t.valueType
121			columns[j].values[i] = t.marshal()
122		}
123	}
124	
125	func (b *block) resizeTagFamilies(tagFamiliesLen int) []columnFamily {
126		tff := b.tagFamilies[:0]
127		if n := tagFamiliesLen - cap(tff); n > 0 {
128			tff = append(tff[:cap(tff)], make([]columnFamily, n)...)
129		}
130		tff = tff[:tagFamiliesLen]
131		b.tagFamilies = tff
132		return tff
133	}
