139	func (b *block) mustWriteTo(sid common.SeriesID, bm *blockMetadata, ww *writers) {
140		b.validate()
141		bm.reset()
142	
143		bm.seriesID = sid
144		bm.uncompressedSizeBytes = b.uncompressedSizeBytes()
145		bm.count = uint64(b.Len())
146	
147		mustWriteTimestampsTo(&bm.timestamps, b.timestamps, b.versions, &ww.timestampsWriter)
148	
149		for ti := range b.tagFamilies {
150			b.marshalTagFamily(b.tagFamilies[ti], bm, ww)
151		}
152	
153		f := b.field
154		cc := f.columns
155		cmm := bm.field.resizeColumnMetadata(len(cc))
156		for i := range cc {
157			cc[i].mustWriteTo(&cmm[i], &ww.fieldValuesWriter)
158		}
159	}
