161	func (b *block) validate() {
162		timestamps := b.timestamps
163		for i := 1; i < len(timestamps); i++ {
164			if timestamps[i-1] > timestamps[i] {
165				logger.Panicf("log entries must be sorted by timestamp; got the previous entry with bigger timestamp %d than the current entry with timestamp %d",
166					timestamps[i-1], timestamps[i])
167			}
168		}
169	
170		itemsCount := len(timestamps)
171		tff := b.tagFamilies
172		for _, tf := range tff {
173			for _, c := range tf.columns {
174				if len(c.values) != itemsCount {
175					logger.Panicf("unexpected number of values for tags %q: got %d; want %d", c.name, len(c.values), itemsCount)
176				}
177			}
178		}
179		ff := b.field
180		for _, f := range ff.columns {
181			if len(f.values) != itemsCount {
182				logger.Panicf("unexpected number of values for fields %q: got %d; want %d", f.name, len(f.values), itemsCount)
183			}
184		}
185	}
