187	func (b *block) marshalTagFamily(tf columnFamily, bm *blockMetadata, ww *writers) {
188		hw, w := ww.getColumnMetadataWriterAndColumnWriter(tf.name)
189		cc := tf.columns
190		if bm.tagType == nil {
191			bm.tagType = make(tagType)
192		}
193		tagTypes := bm.tagType[tf.name]
194		if tagTypes == nil {
195			tagTypes = make(map[string]pbv1.ValueType, len(cc))
196			bm.tagType[tf.name] = tagTypes
197		}
198		cfm := generateColumnFamilyMetadata()
199		cmm := cfm.resizeColumnMetadata(len(cc))
200		for i := range cc {
201			cc[i].mustWriteTo(&cmm[i], w)
202			tagTypes[cc[i].name] = cc[i].valueType
203		}
204		bb := bigValuePool.Generate()
205		defer bigValuePool.Release(bb)
206		bb.Buf = cfm.marshal(bb.Buf)
207		releaseColumnFamilyMetadata(cfm)
208		tfm := bm.getTagFamilyMetadata(tf.name)
209		tfm.offset = hw.bytesWritten
210		tfm.size = uint64(len(bb.Buf))
211		if tfm.size > maxTagFamiliesMetadataSize {
212			logger.Panicf("too big columnFamilyMetadataSize: %d bytes; mustn't exceed %d bytes", tfm.size, maxTagFamiliesMetadataSize)
213		}
214		hw.MustWrite(bb.Buf)
215	}
216	
217	func (b *block) unmarshalTagFamily(decoder *encoding.BytesBlockDecoder, tfIndex int, name string,
218		columnFamilyMetadataBlock *dataBlock, tagProjection []string, metaReader, valueReader fs.Reader, count int,
219		schemaTagTypes map[string]pbv1.ValueType,
220	) {
221		if len(tagProjection) < 1 {
222			return
223		}
224		bb := bigValuePool.Generate()
225		bb.Buf = bytes.ResizeExact(bb.Buf, int(columnFamilyMetadataBlock.size))
226		fs.MustReadData(metaReader, int64(columnFamilyMetadataBlock.offset), bb.Buf)
227		cfm := generateColumnFamilyMetadata()
228		defer releaseColumnFamilyMetadata(cfm)
229		_, err := cfm.unmarshal(bb.Buf)
230		if err != nil {
231			logger.Panicf("%s: cannot unmarshal columnFamilyMetadata: %v", metaReader.Path(), err)
232		}
233		bigValuePool.Release(bb)
234		b.tagFamilies[tfIndex].name = name
235		cc := b.tagFamilies[tfIndex].resizeColumns(len(tagProjection))
236	NEXT:
237		for j := range tagProjection {
238			tp := tagProjection[j]
239			schemaType, hasSchemaType := schemaTagTypes[tp]
240			if hasSchemaType {
241				typedName := encodeTypedColumn(tp, schemaType)
242				for i := range cfm.columnMetadata {
243					if cfm.columnMetadata[i].name == typedName {
244						cc[j].mustReadValues(decoder, valueReader, cfm.columnMetadata[i], uint64(b.Len()))
245						cc[j].name = tp
246						continue NEXT
247					}
248				}
249			}
250			for i := range cfm.columnMetadata {
251				if cfm.columnMetadata[i].name == tp {
252					if hasSchemaType && cfm.columnMetadata[i].valueType != schemaType {
253						continue
254					}
255					cc[j].mustReadValues(decoder, valueReader, cfm.columnMetadata[i], uint64(b.Len()))
256					continue NEXT
257				}
258			}
259			cc[j].name = tp
260			cc[j].valueType = pbv1.ValueTypeUnknown
261			cc[j].resizeValues(count)
262			for k := range cc[j].values {
263				cc[j].values[k] = nil
264			}
265		}
266	}
267	
268	func (b *block) unmarshalTagFamilyFromSeqReaders(decoder *encoding.BytesBlockDecoder, tfIndex int, name string,
269		columnFamilyMetadataBlock *dataBlock, metaReader, valueReader *seqReader,
270	) {
271		if columnFamilyMetadataBlock.offset != metaReader.bytesRead {
272			logger.Panicf("offset %d must be equal to bytesRead %d", columnFamilyMetadataBlock.offset, metaReader.bytesRead)
273		}
274		bb := bigValuePool.Generate()
275		bb.Buf = bytes.ResizeExact(bb.Buf, int(columnFamilyMetadataBlock.size))
276		metaReader.mustReadFull(bb.Buf)
277		cfm := generateColumnFamilyMetadata()
278		defer releaseColumnFamilyMetadata(cfm)
279		_, err := cfm.unmarshal(bb.Buf)
280		if err != nil {
281			logger.Panicf("%s: cannot unmarshal columnFamilyMetadata: %v", metaReader.Path(), err)
282		}
283		bigValuePool.Release(bb)
284		b.tagFamilies[tfIndex].name = name
285	
286		cc := b.tagFamilies[tfIndex].resizeColumns(len(cfm.columnMetadata))
287		for i := range cfm.columnMetadata {
288			cc[i].mustSeqReadValues(decoder, valueReader, cfm.columnMetadata[i], uint64(b.Len()))
289		}
290	}
291	
292	func (b *block) uncompressedSizeBytes() uint64 {
293		dataPointsCount := uint64(b.Len())
294	
295		n := dataPointsCount * (8 + 8) // 8 bytes for timestamp and 8 bytes for version
296	
297		tff := b.tagFamilies
298		for i := range tff {
299			tf := tff[i]
300			n += uint64(len(tf.name))
301			for _, c := range tf.columns {
302				n += uint64(len(c.name))
303				for _, v := range c.values {
304					if len(v) > 0 {
305						n += uint64(len(v))
306					}
307				}
308			}
309		}
310	
311		ff := b.field
312		for i := range ff.columns {
313			c := ff.columns[i]
314			nameLen := uint64(len(c.name))
315			for _, v := range c.values {
316				if len(v) > 0 {
317					n += nameLen + uint64(len(v))
318				}
319			}
320		}
321		return n
322	}
323	
324	func (b *block) mustReadFrom(decoder *encoding.BytesBlockDecoder, p *part, bm blockMetadata, schemaTagTypes map[string]pbv1.ValueType) {
325		b.reset()
326	
327		b.timestamps, b.versions = mustReadTimestampsFrom(b.timestamps, b.versions, &bm.timestamps, int(bm.count), p.timestamps)
328	
329		cc := b.field.resizeColumns(len(bm.field.columnMetadata))
330		for i := range cc {
331			cc[i].mustReadValues(decoder, p.fieldValues, bm.field.columnMetadata[i], bm.count)
332		}
333	
334		_ = b.resizeTagFamilies(len(bm.tagProjection))
335		for i := range bm.tagProjection {
336			name := bm.tagProjection[i].Family
337			block, ok := bm.tagFamilies[name]
338			if !ok {
339				b.tagFamilies[i].name = name
340				b.tagFamilies[i].resizeColumns(len(bm.tagProjection[i].Names))
341				for j := range bm.tagProjection[i].Names {
342					b.tagFamilies[i].columns[j].name = bm.tagProjection[i].Names[j]
343					b.tagFamilies[i].columns[j].valueType = pbv1.ValueTypeUnknown
344					b.tagFamilies[i].columns[j].resizeValues(int(bm.count))
345					for k := range bm.count {
346						b.tagFamilies[i].columns[j].values[k] = nil
347					}
348				}
349				continue
350			}
351			b.unmarshalTagFamily(decoder, i, name, block,
352				bm.tagProjection[i].Names, p.tagFamilyMetadata[name],
353				p.tagFamilies[name], int(bm.count), schemaTagTypes)
354		}
355	}
356	
357	func (b *block) mustSeqReadFrom(decoder *encoding.BytesBlockDecoder, seqReaders *seqReaders, bm blockMetadata) {
358		b.reset()
359	
360		b.timestamps, b.versions = mustSeqReadTimestampsFrom(b.timestamps, b.versions, &bm.timestamps, int(bm.count), &seqReaders.timestamps)
361	
362		cc := b.field.resizeColumns(len(bm.field.columnMetadata))
363		for i := range cc {
364			cc[i].mustSeqReadValues(decoder, &seqReaders.fieldValues, bm.field.columnMetadata[i], bm.count)
365		}
366		_ = b.resizeTagFamilies(len(bm.tagFamilies))
367		keys := make([]string, 0, len(bm.tagFamilies))
368		for k := range bm.tagFamilies {
369			keys = append(keys, k)
370		}
371		sort.Strings(keys)
372		for i, name := range keys {
373			block := bm.tagFamilies[name]
374			b.unmarshalTagFamilyFromSeqReaders(decoder, i, name, block,
375				seqReaders.tagFamilyMetadata[name], seqReaders.tagFamilies[name])
376		}
377	}
