386	func mustWriteTimestampsTo(tm *timestampsMetadata, timestamps, versions []int64, timestampsWriter *writer) {
387		tm.reset()
388	
389		bb := bigValuePool.Generate()
390		defer bigValuePool.Release(bb)
391		bb.Buf, tm.encodeType, tm.min = encoding.Int64ListToBytes(bb.Buf[:0], timestamps)
392		tm.encodeType = encoding.GetVersionType(tm.encodeType)
393		if tm.encodeType == encoding.EncodeTypeUnknown {
394			logger.Panicf("unexpected encodeType %d", tm.encodeType)
395			return
396		}
397		tm.max = timestamps[len(timestamps)-1]
398		tm.offset = timestampsWriter.bytesWritten
399		tm.versionOffset = uint64(len(bb.Buf))
400		timestampsWriter.MustWrite(bb.Buf)
401		bb.Buf, tm.versionEncodeType, tm.versionFirst = encoding.Int64ListToBytes(bb.Buf[:0], versions)
402		tm.size = tm.versionOffset + uint64(len(bb.Buf))
403		timestampsWriter.MustWrite(bb.Buf)
404	}
405	
406	func mustReadTimestampsFrom(timestamps, versions []int64, tm *timestampsMetadata, count int, reader fs.Reader) ([]int64, []int64) {
407		bb := bigValuePool.Generate()
408		defer bigValuePool.Release(bb)
409		bb.Buf = bytes.ResizeExact(bb.Buf, int(tm.size))
410		fs.MustReadData(reader, int64(tm.offset), bb.Buf)
411		return mustDecodeTimestampsWithVersions(timestamps, versions, tm, count, reader.Path(), bb.Buf)
412	}
413	
414	func mustSeqReadTimestampsFrom(timestamps, versions []int64, tm *timestampsMetadata, count int, reader *seqReader) ([]int64, []int64) {
415		if tm.offset != reader.bytesRead {
416			logger.Panicf("offset %d must be equal to bytesRead %d", tm.offset, reader.bytesRead)
417		}
418		bb := bigValuePool.Generate()
419		defer bigValuePool.Release(bb)
420		bb.Buf = bytes.ResizeExact(bb.Buf, int(tm.size))
421		reader.mustReadFull(bb.Buf)
422		return mustDecodeTimestampsWithVersions(timestamps, versions, tm, count, reader.Path(), bb.Buf)
423	}
424	
425	func mustDecodeTimestampsWithVersions(timestamps, versions []int64, tm *timestampsMetadata, count int, path string, src []byte) ([]int64, []int64) {
426		var err error
427		t := encoding.GetCommonType(tm.encodeType)
428		if t == encoding.EncodeTypeUnknown {
429			logger.Panicf("unexpected encodeType %d", tm.encodeType)
430		}
431		if tm.size < tm.versionOffset {
432			logger.Panicf("size %d must be greater than versionOffset %d", tm.size, tm.versionOffset)
433		}
434		timestamps, err = encoding.BytesToInt64List(timestamps, src[:tm.versionOffset], t, tm.min, count)
435		if err != nil {
436			logger.Panicf("%s: cannot unmarshal timestamps with versions: %v", path, err)
437		}
438		versions, err = encoding.BytesToInt64List(versions, src[tm.versionOffset:], tm.versionEncodeType, tm.versionFirst, count)
439		if err != nil {
440			logger.Panicf("%s: cannot unmarshal versions: %v", path, err)
441		}
442		return timestamps, versions
443	}
