509	func (bc *blockCursor) copyAllTo(r *model.MeasureResult, storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
510		tagProjection []model.TagProjection, desc bool,
511	) {
512		var idx, offset int
513		if desc {
514			idx = 0
515			offset = bc.idx + 1
516		} else {
517			idx = bc.idx
518			offset = len(bc.timestamps)
519		}
520		if offset <= idx {
521			return
522		}
523		size := offset - idx
524		r.SID = bc.bm.seriesID
525		r.Timestamps = append(r.Timestamps, bc.timestamps[idx:offset]...)
526		r.Versions = append(r.Versions, bc.versions[idx:offset]...)
527		for i := 0; i < size; i++ {
528			r.ShardIDs = append(r.ShardIDs, bc.shardID)
529		}
530		if desc {
531			slices.Reverse(r.Timestamps)
532			slices.Reverse(r.Versions)
533		}
534		var indexValue map[string]*modelv1.TagValue
535		if storedIndexValue != nil {
536			indexValue = storedIndexValue[r.SID]
537		}
538	OUTER:
539		for _, tp := range tagProjection {
540			tf := model.TagFamily{
541				Name: tp.Family,
542			}
543			var cf *columnFamily
544			for _, tagName := range tp.Names {
545				t := model.Tag{
546					Name: tagName,
547				}
548				if indexValue != nil && indexValue[tagName] != nil {
549					t.Values = make([]*modelv1.TagValue, size)
550					for i := 0; i < size; i++ {
551						t.Values[i] = indexValue[tagName]
552					}
553					tf.Tags = append(tf.Tags, t)
554					continue
555				}
556				if cf == nil {
557					for i := range bc.tagFamilies {
558						if bc.tagFamilies[i].name == tp.Family {
559							cf = &bc.tagFamilies[i]
560							break
561						}
562					}
563				}
564				if cf == nil {
565					for _, n := range tp.Names {
566						t = model.Tag{
567							Name:   n,
568							Values: make([]*modelv1.TagValue, size),
569						}
570						for i := 0; i < size; i++ {
571							t.Values[i] = pbv1.NullTagValue
572						}
573						tf.Tags = append(tf.Tags, t)
574					}
575					r.TagFamilies = append(r.TagFamilies, tf)
576					continue OUTER
577				}
578				var foundTag bool
579				for i := range cf.columns {
580					if cf.columns[i].name == tagName {
581						schemaType, hasSchemaType := bc.schemaTagTypes[tagName]
582						if hasSchemaType && cf.columns[i].valueType == schemaType {
583							for _, v := range cf.columns[i].values[idx:offset] {
584								t.Values = append(t.Values, mustDecodeTagValue(cf.columns[i].valueType, v))
585							}
586						} else {
587							t.Values = make([]*modelv1.TagValue, len(cf.columns[i].values[idx:offset]))
588							for j := range t.Values {
589								t.Values[j] = pbv1.NullTagValue
590							}
591						}
592						foundTag = true
593						break
594					}
595				}
596				if !foundTag {
597					t.Values = make([]*modelv1.TagValue, size)
598					for i := 0; i < size; i++ {
599						t.Values[i] = pbv1.NullTagValue
600					}
601				} else if desc {
602					slices.Reverse(t.Values)
603				}
604				tf.Tags = append(tf.Tags, t)
605			}
606			r.TagFamilies = append(r.TagFamilies, tf)
607		}
608		for _, c := range bc.fields.columns {
609			f := model.Field{
610				Name: c.name,
611			}
612			for _, v := range c.values[idx:offset] {
613				f.Values = append(f.Values, mustDecodeFieldValue(c.valueType, v))
614			}
615			if desc {
616				slices.Reverse(f.Values)
617			}
618			r.Fields = append(r.Fields, f)
619		}
620	}
