622	func (bc *blockCursor) copyTo(r *model.MeasureResult, storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
623		tagProjection []model.TagProjection,
624	) {
625		r.SID = bc.bm.seriesID
626		r.Timestamps = append(r.Timestamps, bc.timestamps[bc.idx])
627		r.Versions = append(r.Versions, bc.versions[bc.idx])
628		r.ShardIDs = append(r.ShardIDs, bc.shardID)
629		var indexValue map[string]*modelv1.TagValue
630		if storedIndexValue != nil {
631			indexValue = storedIndexValue[r.SID]
632		}
633		if len(r.TagFamilies) == 0 {
634			for _, tp := range tagProjection {
635				tf := model.TagFamily{
636					Name: tp.Family,
637				}
638				for _, n := range tp.Names {
639					t := model.Tag{
640						Name: n,
641					}
642					tf.Tags = append(tf.Tags, t)
643				}
644				r.TagFamilies = append(r.TagFamilies, tf)
645			}
646		}
647		for i := range r.TagFamilies {
648			tfName := r.TagFamilies[i].Name
649			var cf *columnFamily
650			for j := range r.TagFamilies[i].Tags {
651				tagName := r.TagFamilies[i].Tags[j].Name
652				if indexValue != nil && indexValue[tagName] != nil {
653					r.TagFamilies[i].Tags[j].Values = append(r.TagFamilies[i].Tags[j].Values, indexValue[tagName])
654					continue
655				}
656				if cf == nil {
657					for i := range bc.tagFamilies {
658						if bc.tagFamilies[i].name == tfName {
659							cf = &bc.tagFamilies[i]
660							break
661						}
662					}
663				}
664				if cf == nil {
665					r.TagFamilies[i].Tags[j].Values = append(r.TagFamilies[i].Tags[j].Values, pbv1.NullTagValue)
666					continue
667				}
668				var foundTag bool
669				for _, c := range cf.columns {
670					if c.name == tagName {
671						schemaType, hasSchemaType := bc.schemaTagTypes[tagName]
672						if hasSchemaType && c.valueType == schemaType {
673							r.TagFamilies[i].Tags[j].Values = append(r.TagFamilies[i].Tags[j].Values, mustDecodeTagValue(c.valueType, c.values[bc.idx]))
674						} else {
675							r.TagFamilies[i].Tags[j].Values = append(r.TagFamilies[i].Tags[j].Values, pbv1.NullTagValue)
676						}
677						foundTag = true
678						break
679					}
680				}
681				if !foundTag {
682					r.TagFamilies[i].Tags[j].Values = append(r.TagFamilies[i].Tags[j].Values, pbv1.NullTagValue)
683				}
684			}
685		}
686	
687		if len(r.Fields) == 0 {
688			for _, n := range bc.fieldProjection {
689				f := model.Field{
690					Name: n,
691				}
692				r.Fields = append(r.Fields, f)
693			}
694		}
695		for i, c := range bc.fields.columns {
696			r.Fields[i].Values = append(r.Fields[i].Values, mustDecodeFieldValue(c.valueType, c.values[bc.idx]))
697		}
698	}
