700	func (bc *blockCursor) mergeTopNResult(r *model.MeasureResult, storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
701		topN int32, sort modelv1.Sort, fieldType databasev1.FieldType,
702	) {
703		r.SID = bc.bm.seriesID
704		var indexValue map[string]*modelv1.TagValue
705		if storedIndexValue != nil {
706			indexValue = storedIndexValue[r.SID]
707		}
708		for i := range r.TagFamilies {
709			tfName := r.TagFamilies[i].Name
710			var cf *columnFamily
711			for j := range r.TagFamilies[i].Tags {
712				tagName := r.TagFamilies[i].Tags[j].Name
713				if indexValue != nil && indexValue[tagName] != nil {
714					r.TagFamilies[i].Tags[j].Values[len(r.TagFamilies[i].Tags[j].Values)-1] = indexValue[tagName]
715					continue
716				}
717				if cf == nil {
718					for i := range bc.tagFamilies {
719						if bc.tagFamilies[i].name == tfName {
720							cf = &bc.tagFamilies[i]
721							break
722						}
723					}
724				}
725				for _, c := range cf.columns {
726					if c.name == tagName {
727						schemaType, hasSchemaType := bc.schemaTagTypes[tagName]
728						if hasSchemaType && c.valueType == schemaType {
729							r.TagFamilies[i].Tags[j].Values[len(r.TagFamilies[i].Tags[j].Values)-1] = mustDecodeTagValue(c.valueType, c.values[bc.idx])
730						} else {
731							r.TagFamilies[i].Tags[j].Values[len(r.TagFamilies[i].Tags[j].Values)-1] = pbv1.NullTagValue
732						}
733						break
734					}
735				}
736			}
737		}
738	
739		decoder := GenerateTopNValuesDecoder()
740		defer ReleaseTopNValuesDecoder(decoder)
741	
742		uTimestamps := uint64(bc.timestamps[bc.idx])
743	
744		for i, c := range bc.fields.columns {
745			srcFieldValue := r.Fields[i].Values[len(r.Fields[i].Values)-1]
746			destFieldValue := mustDecodeFieldValue(c.valueType, c.values[bc.idx])
747	
748			merged, mergeErr := MergeTopNBinaryValues(
749				srcFieldValue.GetBinaryData(),
750				destFieldValue.GetBinaryData(),
751				topN,
752				sort,
753				decoder,
754				uTimestamps,
755				r.Versions[len(r.Versions)-1],
756				bc.versions[bc.idx],
757				fieldType,
758			)
759			if mergeErr != nil {
760				log.Error().Err(mergeErr).Msg("failed to merge topN values, skip current batch")
761				continue
762			}
763	
764			r.Fields[i].Values[len(r.Fields[i].Values)-1] = &modelv1.FieldValue{
765				Value: &modelv1.FieldValue_BinaryData{
766					BinaryData: merged,
767				},
768			}
769		}
770	
771		if bc.versions[bc.idx] > r.Versions[len(r.Versions)-1] {
772			r.Versions[len(r.Versions)-1] = bc.versions[bc.idx]
773		}
774	}
