818	func (bc *blockCursor) loadData(tmpBlock *block) bool {
819		tmpBlock.reset()
820		cfm := make([]columnMetadata, 0, len(bc.fieldProjection))
821	NEXT_FIELD:
822		for _, fp := range bc.fieldProjection {
823			for _, cm := range bc.bm.field.columnMetadata {
824				if cm.name == fp {
825					cfm = append(cfm, cm)
826					continue NEXT_FIELD
827				}
828			}
829			cfm = append(cfm, columnMetadata{
830				name:      fp,
831				valueType: pbv1.ValueTypeUnknown,
832			})
833		}
834		bc.bm.field.columnMetadata = cfm
835		bc.bm.tagProjection = bc.tagProjection
836		var tf map[string]*dataBlock
837		for _, tp := range bc.tagProjection {
838			for tfName, block := range bc.bm.tagFamilies {
839				if tp.Family == tfName {
840					if tf == nil {
841						tf = make(map[string]*dataBlock, len(bc.tagProjection))
842					}
843					tf[tfName] = block
844				}
845			}
846		}
847		bc.bm.tagFamilies = tf
848		tmpBlock.mustReadFrom(&bc.columnValuesDecoder, bc.p, bc.bm, bc.schemaTagTypes)
849	
850		start, end, ok := timestamp.FindRange(tmpBlock.timestamps, bc.minTimestamp, bc.maxTimestamp)
851		if !ok {
852			return false
853		}
854		bc.timestamps = append(bc.timestamps, tmpBlock.timestamps[start:end+1]...)
855		bc.versions = append(bc.versions, tmpBlock.versions[start:end+1]...)
856	
857		for _, cf := range tmpBlock.tagFamilies {
858			tf := columnFamily{
859				name: cf.name,
860			}
861			for i := range cf.columns {
862				column := column{
863					name:      cf.columns[i].name,
864					valueType: cf.columns[i].valueType,
865				}
866				if len(cf.columns[i].values) == 0 {
867					continue
868				}
869				if len(cf.columns[i].values) != len(tmpBlock.timestamps) {
870					logger.Panicf("unexpected number of values for tags %q: got %d; want %d", cf.columns[i].name, len(cf.columns[i].values), len(tmpBlock.timestamps))
871				}
872				column.values = append(column.values, cf.columns[i].values[start:end+1]...)
873				tf.columns = append(tf.columns, column)
874			}
875			bc.tagFamilies = append(bc.tagFamilies, tf)
876		}
877		bc.fields.name = tmpBlock.field.name
878		for i := range tmpBlock.field.columns {
879			if len(tmpBlock.field.columns[i].values) == 0 {
880				continue
881			}
882			if len(tmpBlock.field.columns[i].values) != len(tmpBlock.timestamps) {
883				logger.Panicf("unexpected number of values for fields %q: got %d; want %d",
884					tmpBlock.field.columns[i].name, len(tmpBlock.field.columns[i].values), len(tmpBlock.timestamps))
885			}
886			c := column{
887				name:      tmpBlock.field.columns[i].name,
888				valueType: tmpBlock.field.columns[i].valueType,
889			}
890	
891			c.values = append(c.values, tmpBlock.field.columns[i].values[start:end+1]...)
892			bc.fields.columns = append(bc.fields.columns, c)
893		}
894		return true
895	}
