943	func (bi *blockPointer) append(b *blockPointer, offset int) {
944		if offset <= b.idx {
945			return
946		}
947	
948		bi.appendTagFamilies(b, offset)
949	
950		if len(bi.field.columns) == 0 && len(b.field.columns) > 0 {
951			fullFieldAppend(bi, b, offset)
952		} else {
953			if err := fastFieldAppend(bi, b, offset); err != nil {
954				if log.Debug().Enabled() {
955					log.Debug().Msgf("fastFieldAppend failed: %v; falling back to fullFieldAppend", err)
956				}
957				fullFieldAppend(bi, b, offset)
958			}
959		}
960	
961		assertIdxAndOffset("timestamps", len(b.timestamps), bi.idx, offset)
962		bi.timestamps = append(bi.timestamps, b.timestamps[b.idx:offset]...)
963		assertIdxAndOffset("versions", len(b.versions), bi.idx, offset)
964		bi.versions = append(bi.versions, b.versions[b.idx:offset]...)
965	}
