967	func fastTagAppend(bi, b *blockPointer, offset int) error {
968		if len(bi.tagFamilies) != len(b.tagFamilies) {
969			return fmt.Errorf("unexpected number of tag families: got %d; want %d", len(b.tagFamilies), len(bi.tagFamilies))
970		}
971		existingDataSize := len(bi.timestamps)
972		for i := range bi.tagFamilies {
973			if bi.tagFamilies[i].name != b.tagFamilies[i].name {
974				rollbackFastTagAppend(bi, existingDataSize)
975				return fmt.Errorf("unexpected tag family name: got %q; want %q", b.tagFamilies[i].name, bi.tagFamilies[i].name)
976			}
977			if len(bi.tagFamilies[i].columns) != len(b.tagFamilies[i].columns) {
978				rollbackFastTagAppend(bi, existingDataSize)
979				return fmt.Errorf("unexpected number of tags for tag family %q: got %d; want %d",
980					bi.tagFamilies[i].name, len(b.tagFamilies[i].columns), len(bi.tagFamilies[i].columns))
981			}
982			for j := range bi.tagFamilies[i].columns {
983				if bi.tagFamilies[i].columns[j].name != b.tagFamilies[i].columns[j].name {
984					rollbackFastTagAppend(bi, existingDataSize)
985					return fmt.Errorf("unexpected tag name for tag family %q: got %q; want %q",
986						bi.tagFamilies[i].name, b.tagFamilies[i].columns[j].name, bi.tagFamilies[i].columns[j].name)
987				}
988				assertIdxAndOffset(b.tagFamilies[i].columns[j].name, len(b.tagFamilies[i].columns[j].values), b.idx, offset)
989				bi.tagFamilies[i].columns[j].values = append(bi.tagFamilies[i].columns[j].values, b.tagFamilies[i].columns[j].values[b.idx:offset]...)
990			}
991		}
992		return nil
993	}
994	
995	func rollbackFastTagAppend(bi *blockPointer, existingDataSize int) {
996		for i := range bi.tagFamilies {
997			for j := range bi.tagFamilies[i].columns {
998				if len(bi.tagFamilies[i].columns[j].values) > existingDataSize {
999					bi.tagFamilies[i].columns[j].values = bi.tagFamilies[i].columns[j].values[:existingDataSize]
1000				}
1001			}
1002		}
1003	}
