1005	func fullTagAppend(bi, b *blockPointer, offset int) {
1006		existDataSize := len(bi.timestamps)
1007		appendTagFamilies := func(tf columnFamily) {
1008			tagFamily := columnFamily{name: tf.name}
1009			for i := range tf.columns {
1010				assertIdxAndOffset(tf.columns[i].name, len(tf.columns[i].values), b.idx, offset)
1011				col := column{name: tf.columns[i].name, valueType: tf.columns[i].valueType}
1012				for j := 0; j < existDataSize; j++ {
1013					col.values = append(col.values, nil)
1014				}
1015				col.values = append(col.values, tf.columns[i].values[b.idx:offset]...)
1016				tagFamily.columns = append(tagFamily.columns, col)
1017			}
1018			bi.tagFamilies = append(bi.tagFamilies, tagFamily)
1019		}
1020		if len(bi.tagFamilies) == 0 {
1021			for _, tf := range b.tagFamilies {
1022				appendTagFamilies(tf)
1023			}
1024			return
1025		}
1026	
1027		tagFamilyMap := make(map[string]*columnFamily)
1028		for i := range bi.tagFamilies {
1029			tagFamilyMap[bi.tagFamilies[i].name] = &bi.tagFamilies[i]
1030		}
1031	
1032		for _, tf := range b.tagFamilies {
1033			if existingTagFamily, exists := tagFamilyMap[tf.name]; exists {
1034				columnMap := make(map[string]*column)
1035				for i := range existingTagFamily.columns {
1036					columnMap[existingTagFamily.columns[i].name] = &existingTagFamily.columns[i]
1037				}
1038	
1039				for _, c := range tf.columns {
1040					if existingColumn, exists := columnMap[c.name]; exists {
1041						assertIdxAndOffset(c.name, len(c.values), b.idx, offset)
1042						existingColumn.values = append(existingColumn.values, c.values[b.idx:offset]...)
1043					} else {
1044						assertIdxAndOffset(c.name, len(c.values), b.idx, offset)
1045						col := column{name: c.name, valueType: c.valueType}
1046						for j := 0; j < existDataSize; j++ {
1047							col.values = append(col.values, nil)
1048						}
1049						col.values = append(col.values, c.values[b.idx:offset]...)
1050						existingTagFamily.columns = append(existingTagFamily.columns, col)
1051					}
1052				}
1053			} else {
1054				appendTagFamilies(tf)
1055			}
1056		}
1057		for k := range tagFamilyMap {
1058			delete(tagFamilyMap, k)
1059		}
1060		for i := range b.tagFamilies {
1061			tagFamilyMap[b.tagFamilies[i].name] = &b.tagFamilies[i]
1062		}
1063		emptySize := offset - b.idx
1064		for _, tf := range bi.tagFamilies {
1065			if _, exists := tagFamilyMap[tf.name]; !exists {
1066				for i := range tf.columns {
1067					for j := 0; j < emptySize; j++ {
1068						tf.columns[i].values = append(tf.columns[i].values, nil)
1069					}
1070				}
1071			} else {
1072				existingTagFamily := tagFamilyMap[tf.name]
1073				columnMap := make(map[string]*column)
1074				for i := range existingTagFamily.columns {
1075					columnMap[existingTagFamily.columns[i].name] = &existingTagFamily.columns[i]
1076				}
1077				for i := range tf.columns {
1078					if _, exists := columnMap[tf.columns[i].name]; !exists {
1079						for j := 0; j < emptySize; j++ {
1080							tf.columns[i].values = append(tf.columns[i].values, nil)
1081						}
1082					}
1083				}
1084			}
1085		}
1086	}
