1116			return
1117		}
1118	
1119		fieldMap := make(map[string]*column)
1120		for i := range bi.field.columns {
1121			fieldMap[bi.field.columns[i].name] = &bi.field.columns[i]
1122		}
1123	
1124		for _, c := range b.field.columns {
1125			if existingField, exists := fieldMap[c.name]; exists {
1126				assertIdxAndOffset(c.name, len(c.values), b.idx, offset)
1127				existingField.values = append(existingField.values, c.values[b.idx:offset]...)
1128			} else {
1129				appendFields(c)
1130			}
1131		}
1132		for k := range fieldMap {
1133			delete(fieldMap, k)
1134		}
1135		for i := range b.field.columns {
1136			fieldMap[b.field.columns[i].name] = &b.field.columns[i]
1137		}
1138	
1139		emptySize := offset - b.idx
1140		for i := range bi.field.columns {
1141			if _, exists := fieldMap[bi.field.columns[i].name]; !exists {
1142				for j := 0; j < emptySize; j++ {
1143					bi.field.columns[i].values = append(bi.field.columns[i].values, nil)
1144				}
1145			}
1146		}
1147	}
