1149	func (bi *blockPointer) mergeAndAppendTopN(
1150		left *blockPointer, leftIdx int, right *blockPointer, rightIdx int,
1151		topN int32, sort modelv1.Sort, fieldType databasev1.FieldType,
1152	) {
1153		decoder := GenerateTopNValuesDecoder()
1154		defer ReleaseTopNValuesDecoder(decoder)
1155	
1156		uTimestamp := uint64(right.timestamps[rightIdx])
1157		leftVer, rightVer := left.versions[leftIdx], right.versions[rightIdx]
1158	
1159		if len(bi.field.columns) == 0 {
1160			for _, c := range right.field.columns {
1161				bi.field.columns = append(bi.field.columns, column{
1162					name:      c.name,
1163					valueType: c.valueType,
1164					values:    make([][]byte, 0),
1165				})
1166			}
1167		}
1168	
1169		for idx := range right.field.columns {
1170			merged, mergeErr := MergeTopNBinaryValues(
1171				left.field.columns[idx].values[leftIdx],
1172				right.field.columns[idx].values[rightIdx],
1173				topN,
1174				sort,
1175				decoder,
1176				uTimestamp,
1177				leftVer,
1178				rightVer,
1179				fieldType,
1180			)
1181			if mergeErr != nil {
1182				log.Error().Err(mergeErr).Msg("both sides of topN value are malformed, append empty value")
1183				bi.field.columns[idx].values = append(bi.field.columns[idx].values, []byte{})
1184				continue
1185			}
1186	
1187			bi.field.columns[idx].values = append(bi.field.columns[idx].values, merged)
1188		}
1189	
1190		if rightVer >= leftVer {
1191			bi.appendTagFamilies(right, rightIdx+1)
1192			bi.versions = append(bi.versions, rightVer)
1193		} else {
1194			bi.appendTagFamilies(left, leftIdx+1)
1195			bi.versions = append(bi.versions, leftVer)
1196		}
1197		bi.timestamps = append(bi.timestamps, right.timestamps[rightIdx])
1198	}
1199	
1200	func (bi *blockPointer) appendTagFamilies(b *blockPointer, offset int) {
1201		if len(bi.tagFamilies) == 0 && len(b.tagFamilies) > 0 {
1202			fullTagAppend(bi, b, offset)
1203			return
1204		}
1205	
1206		if err := fastTagAppend(bi, b, offset); err != nil {
1207			if log.Debug().Enabled() {
1208				log.Debug().Msgf("fastTagAppend failed: %v; falling back to fullTagAppend", err)
1209			}
1210			fullTagAppend(bi, b, offset)
1211		}
1212	}
