1214	func assertIdxAndOffset(name string, length int, idx int, offset int) {
1215		if idx >= offset {
1216			logger.Panicf("%q idx %d must be less than offset %d", name, idx, offset)
1217		}
1218		if offset > length {
1219			logger.Panicf("%q offset %d must be less than or equal to length %d", name, offset, length)
1220		}
1221	}
1222	
1223	func (bi *blockPointer) isFull() bool {
1224		return bi.bm.count >= maxBlockLength || bi.bm.uncompressedSizeBytes >= maxUncompressedBlockSize
1225	}
