63	type blockMetadata struct {
64		tagFamilies           map[string]*dataBlock
65		tagType               tagType
66		field                 columnFamilyMetadata
67		tagProjection         []model.TagProjection
68		timestamps            timestampsMetadata
69		seriesID              common.SeriesID
70		uncompressedSizeBytes uint64
71		count                 uint64
72	}
