74	func (bm *blockMetadata) copyFrom(src *blockMetadata) {
75		bm.seriesID = src.seriesID
76		bm.uncompressedSizeBytes = src.uncompressedSizeBytes
77		bm.count = src.count
78		bm.timestamps.copyFrom(&src.timestamps)
79		if src.tagType == nil {
80			bm.tagType = nil
81		} else {
82			if bm.tagType == nil {
83				bm.tagType = make(tagType, len(src.tagType))
84			} else {
85				bm.tagType.reset()
86			}
87			bm.tagType.copyFrom(src.tagType)
88		}
89		for k, db := range src.tagFamilies {
90			if bm.tagFamilies == nil {
91				bm.tagFamilies = make(map[string]*dataBlock)
92			}
93			bm.tagFamilies[k] = &dataBlock{}
94			bm.tagFamilies[k].copyFrom(db)
95		}
96		bm.field.copyFrom(&src.field)
97	}
