99	func (bm *blockMetadata) getTagFamilyMetadata(name string) *dataBlock {
100		if bm.tagFamilies == nil {
101			bm.tagFamilies = make(map[string]*dataBlock)
102		}
103		tf, ok := bm.tagFamilies[name]
104		if !ok {
105			tf = &dataBlock{}
106			bm.tagFamilies[name] = tf
107		}
108		return tf
109	}
