111	func (bm *blockMetadata) reset() {
112		bm.seriesID = 0
113		bm.uncompressedSizeBytes = 0
114		bm.count = 0
115		bm.timestamps.reset()
116		bm.field.reset()
117		if bm.tagType == nil {
118			bm.tagType = make(tagType)
119		} else {
120			bm.tagType.reset()
121		}
122		for k := range bm.tagFamilies {
123			bm.tagFamilies[k].reset()
124			delete(bm.tagFamilies, k)
125		}
126		bm.tagProjection = bm.tagProjection[:0]
127	}
128	
129	func (bm *blockMetadata) marshal(dst []byte) []byte {
130		dst = bm.seriesID.AppendToBytes(dst)
131		dst = encoding.VarUint64ToBytes(dst, bm.uncompressedSizeBytes)
132		dst = encoding.VarUint64ToBytes(dst, bm.count)
133		dst = bm.timestamps.marshal(dst)
134		dst = encoding.VarUint64ToBytes(dst, uint64(len(bm.tagFamilies)))
135		// make sure the order of tagFamilies is stable
136		keys := make([]string, 0, len(bm.tagFamilies))
137		for k := range bm.tagFamilies {
138			keys = append(keys, k)
139		}
140		sort.Strings(keys)
141		for _, name := range keys {
142			cf := bm.tagFamilies[name]
143			dst = encoding.EncodeBytes(dst, convert.StringToBytes(name))
144			dst = cf.marshal(dst)
145		}
146		return bm.field.marshal(dst)
147	}
148	
149	func (bm *blockMetadata) unmarshal(src []byte) ([]byte, error) {
150		if len(src) < 8 {
151			return nil, errors.New("cannot unmarshal blockMetadata from less than 8 bytes")
152		}
153		bm.seriesID = common.SeriesID(encoding.BytesToUint64(src))
154		src = src[8:]
155		src, n := encoding.BytesToVarUint64(src)
156		bm.uncompressedSizeBytes = n
157	
158		src, n = encoding.BytesToVarUint64(src)
159		bm.count = n
160		src = bm.timestamps.unmarshal(src)
161		src, n = encoding.BytesToVarUint64(src)
162		if n > 0 {
163			if bm.tagFamilies == nil {
164				bm.tagFamilies = make(map[string]*dataBlock, n)
165			}
166			var nameBytes []byte
167			var err error
168			for i := uint64(0); i < n; i++ {
169				src, nameBytes, err = encoding.DecodeBytes(src)
170				if err != nil {
171					return nil, fmt.Errorf("cannot unmarshal tagFamily name: %w", err)
172				}
173				tf := &dataBlock{}
174				src = tf.unmarshal(src)
175				bm.tagFamilies[string(nameBytes)] = tf
176			}
177		}
178		var err error
179		src, err = bm.field.unmarshal(src)
180		if err != nil {
181			return nil, fmt.Errorf("cannot unmarshal columnFamilyMetadata: %w", err)
182		}
183		return src, nil
184	}
185	
186	func (bm *blockMetadata) less(other *blockMetadata) bool {
187		if bm.seriesID == other.seriesID {
188			return bm.timestamps.min < other.timestamps.min
189		}
190		return bm.seriesID < other.seriesID
191	}
