212	func (bma *blockMetadataArray) Size() uint64 {
213		// Size of the struct itself (contains slice header)
214		size := uint64(unsafe.Sizeof(*bma))
215	
216		// Size of each blockMetadata struct (just the static parts)
217		for i := range bma.arr {
218			bm := &bma.arr[i]
219			// Base struct size (fixed fields only)
220			size += uint64(unsafe.Sizeof(blockMetadata{}))
221	
222			if bm.tagFamilies != nil {
223				// Map overhead + entries (key string header + key data + pointer to dataBlock + actual dataBlock)
224				mapOverhead := uint64(48) // Approximate Go map overhead
225				size += mapOverhead
226				for name, db := range bm.tagFamilies {
227					if db != nil {
228						size += uint64(unsafe.Sizeof("")) + uint64(len(name)) // key
229						size += uint64(unsafe.Sizeof((*dataBlock)(nil)))      // pointer
230						size += uint64(unsafe.Sizeof(*db))                    // actual dataBlock value

