36	type partIter struct {
37		err                  error
38		p                    *part
39		c                    storage.Cache
40		curBlock             *blockMetadata
41		sids                 []common.SeriesID
42		primaryBlockMetadata []primaryBlockMetadata
43		bms                  []blockMetadata
