51	func (pi *partIter) reset() {
52		pi.curBlock = nil
53		pi.p = nil
54		pi.c = nil
55		pi.sids = nil
56		pi.sidIdx = 0
57		pi.primaryBlockMetadata = nil
58		pi.bms = nil
59		pi.compressedPrimaryBuf = pi.compressedPrimaryBuf[:0]
60		pi.primaryBuf = pi.primaryBuf[:0]
