64	func (pi *partIter) init(p *part, sids []common.SeriesID, minTimestamp, maxTimestamp int64) {
65		pi.reset()
66		pi.curBlock = &blockMetadata{}
67		pi.p = p
68		pi.c = p.cache
69	
70		pi.sids = sids
71		pi.minTimestamp = minTimestamp
72		pi.maxTimestamp = maxTimestamp
73	
74		pi.primaryBlockMetadata = p.primaryBlockMetadata
75	
76		pi.nextSeriesID()
