78	
79	func (pi *partIter) nextBlock() bool {
80		for {
81			if pi.err != nil {
82				return false
83			}
84			if len(pi.bms) == 0 {
85				if !pi.loadNextBlockMetadata() {
86					return false
87				}
88			}
89			if pi.findBlock() {
90				return true
91			}
92		}
93	}
94	
95	func (pi *partIter) error() error {
96		if errors.Is(pi.err, io.EOF) {
97			return nil
98		}
99		return pi.err
100	}
101	
102	func (pi *partIter) nextSeriesID() bool {
103		if pi.sidIdx >= len(pi.sids) {
104			pi.err = io.EOF
105			return false
106		}
107		pi.curBlock.seriesID = pi.sids[pi.sidIdx]
108		pi.sidIdx++
109		return true
110	}
111	
112	func (pi *partIter) searchTargetSeriesID(sid common.SeriesID) bool {
113		if pi.curBlock.seriesID >= sid {
114			return true
115		}
116		if !pi.nextSeriesID() {
117			return false
118		}
119		if pi.curBlock.seriesID >= sid {
120			return true
121		}
122		sids := pi.sids[pi.sidIdx:]
123		pi.sidIdx += sort.Search(len(sids), func(i int) bool {
124			return sid <= sids[i]
125		})
126		if pi.sidIdx >= len(pi.sids) {
127			pi.sidIdx = len(pi.sids)
128			pi.err = io.EOF
129			return false
130		}
131		pi.curBlock.seriesID = pi.sids[pi.sidIdx]
132		pi.sidIdx++
133		return true
134	}
135	
136	func (pi *partIter) loadNextBlockMetadata() bool {
137		for len(pi.primaryBlockMetadata) > 0 {
138			if !pi.searchTargetSeriesID(pi.primaryBlockMetadata[0].seriesID) {
139				return false
140			}
141			pi.primaryBlockMetadata = searchPBM(pi.primaryBlockMetadata, pi.curBlock.seriesID)
142	
143			pbm := &pi.primaryBlockMetadata[0]
144			pi.primaryBlockMetadata = pi.primaryBlockMetadata[1:]
145			if pi.curBlock.seriesID < pbm.seriesID {
146				logger.Panicf("invariant violation: pi.curBlock.seriesID cannot be smaller than pbm.seriesID; got %+v vs %+v", &pi.curBlock.seriesID, &pbm.seriesID)
147			}
148	
149			if pbm.maxTimestamp < pi.minTimestamp || pbm.minTimestamp > pi.maxTimestamp {
150				continue
151			}
152	
153			err := pi.readPrimaryBlock(pbm)
154			if err != nil {
155				pi.err = fmt.Errorf("cannot read primary block for part %q at offset %d with size %d: %w",
156					&pi.p.partMetadata, pbm.offset, pbm.size, err)
157				return false
158			}
159			return true
160		}
161		pi.err = io.EOF
162		return false
163	}
164	
165	func searchPBM(pbmIndex []primaryBlockMetadata, sid common.SeriesID) []primaryBlockMetadata {
166		if sid < pbmIndex[0].seriesID {
167			logger.Panicf("invariant violation: sid cannot be smaller than pbmIndex[0]; got %d vs %d", sid, &pbmIndex[0].seriesID)
168		}
169	
170		if sid == pbmIndex[0].seriesID {
171			return pbmIndex
172		}
173	
174		n := sort.Search(len(pbmIndex), func(i int) bool {
175			return sid <= pbmIndex[i].seriesID
176		})
177		if n == 0 {
178			logger.Panicf("invariant violation: sort.Search returned 0 for sid > pbmIndex[0].seriesID; sid=%+v; pbmIndex[0].seriesID=%+v",
179				sid, &pbmIndex[0].seriesID)
180		}
181		return pbmIndex[n-1:]
182	}
183	
184	func (pi *partIter) readPrimaryBlock(mr *primaryBlockMetadata) error {
185		value := pi.c.Get(storage.NewEntryKey(pi.p.partMetadata.ID, mr.offset))
186		if value != nil {
187			bma := value.(*blockMetadataArray)
188			pi.bms = bma.arr
189			return nil
190		}
191	
192		pi.compressedPrimaryBuf = bytes.ResizeOver(pi.compressedPrimaryBuf, int(mr.size))
193		fs.MustReadData(pi.p.primary, int64(mr.offset), pi.compressedPrimaryBuf)
194	
195		var err error
196		pi.primaryBuf, err = zstd.Decompress(pi.primaryBuf[:0], pi.compressedPrimaryBuf)
197		if err != nil {
198			return fmt.Errorf("cannot decompress index block: %w", err)
199		}
200		bma := &blockMetadataArray{}
201		bma.arr, err = unmarshalBlockMetadata(bma.arr[:0], pi.primaryBuf)
202		if err != nil {
203			return fmt.Errorf("cannot unmarshal index block: %w", err)
204		}
205		pi.c.Put(storage.NewEntryKey(pi.p.partMetadata.ID, mr.offset), bma)
206		pi.bms = bma.arr
207		return nil
208	}
209	
210	func (pi *partIter) findBlock() bool {
211		bhs := pi.bms
212		for len(bhs) > 0 {
213			sid := pi.curBlock.seriesID
214			if bhs[0].seriesID < sid {
215				n := sort.Search(len(bhs), func(i int) bool {
216					return sid <= bhs[i].seriesID
217				})
218				if n == len(bhs) {
219					break
220				}
221				bhs = bhs[n:]
222			}
223			bm := &bhs[0]
224	
225			if bm.seriesID != sid {
226				if !pi.searchTargetSeriesID(bm.seriesID) {
227					return false
228				}
229				continue
230			}
231	
232			if bm.timestamps.max < pi.minTimestamp {
233				bhs = bhs[1:]
234				continue
235			}
236			if bm.timestamps.min > pi.maxTimestamp {
237				if !pi.nextSeriesID() {
238					return false
239				}
240				continue
241			}
242	
243			pi.curBlock.copyFrom(bm)
244	
245			pi.bms = bhs[1:]
246			return true
247		}
248		pi.bms = nil
249		return false
250	}
