288	func (pmi *partMergeIter) nextBlockMetadata() bool {
289		if pmi.err != nil {
290			return false
291		}
292		pmi.block.reset()
293		if len(pmi.primaryBuf) == 0 {
294			if err := pmi.loadPrimaryBuf(); err != nil {
295				pmi.err = err
296				return false
297			}
298		}
299		if err := pmi.loadBlockMetadata(); err != nil {
300			pmi.err = err
301			return false
302		}
303		return true
