306	func (pmi *partMergeIter) loadPrimaryBuf() error {
307		if pmi.primaryMetadataIdx >= len(pmi.primaryBlockMetadata) {
308			return io.EOF
309		}
310		pm := pmi.primaryBlockMetadata[pmi.primaryMetadataIdx]
311		pmi.compressedPrimaryBuf = bytes.ResizeOver(pmi.compressedPrimaryBuf, int(pm.size))
312		pmi.seqReaders.primary.mustReadFull(pmi.compressedPrimaryBuf)
313		var err error
314		pmi.primaryBuf, err = zstd.Decompress(pmi.primaryBuf[:0], pmi.compressedPrimaryBuf)
315		if err != nil {
316			return fmt.Errorf("cannot decompress primary block: %w", err)
317		}
318		pmi.primaryMetadataIdx++
319		return nil
320	}
321	
322	func (pmi *partMergeIter) loadBlockMetadata() error {
323		pmi.block.reset()
324		var err error
325		pmi.primaryBuf, err = pmi.block.bm.unmarshal(pmi.primaryBuf)
326		if err != nil {
327			pm := pmi.primaryBlockMetadata[pmi.primaryMetadataIdx-1]
328			return fmt.Errorf("can't read block metadata from primary at %d: %w", pm.offset, err)
329		}
330		return nil
331	}
