333	func (pmi *partMergeIter) mustLoadBlockData(decoder *encoding.BytesBlockDecoder, block *blockPointer) {
334		block.block.mustSeqReadFrom(decoder, &pmi.seqReaders, pmi.block.bm)
335	}
